text:
#stage {
  --ground: #FAFBF8;
  --main: #192823;
  --second: #4D6158;
  --accent: #155B55;
  --on-brand: #FFFFFF;
  --tint: #DBEDE2;
  --correct: #286044;
  --incorrect: #9A3731;
  --nav-bg: color-mix(in srgb, var(--main) 4%, var(--ground));
  --hair: color-mix(in srgb, var(--main) 14%, transparent);
  --hover-bg: color-mix(in srgb, var(--main) 7%, var(--ground));
  --disabled-bg: color-mix(in srgb, var(--main) 7%, var(--ground));
  --scrim: color-mix(in srgb, var(--main) 40%, transparent);
  color: var(--main);
  font-family: var(--sans, system-ui, sans-serif);
}
.ground {
  position: absolute;
  inset: 0;
  background: var(--ground);
  overflow: hidden;
}
.study-header {
  position: absolute;
  left: 72px;
  right: 72px;
  top: 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.study-kicker {
  font-size: 20px;
  font-weight: 600;
  line-height: 28px;
  color: var(--second);
}
.study-title {
  font-size: 32px;
  font-weight: 700;
  line-height: 40px;
  color: var(--main);
  margin: 0;
}
.study-badge {
  padding: 8px 16px;
  border-radius: 6px;
  background: var(--tint);
  color: var(--accent);
  font-size: 18px;
  font-weight: 600;
  line-height: 24px;
}
.study-footer {
  position: absolute;
  left: 72px;
  right: 72px;
  bottom: 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 16px;
  line-height: 22px;
  color: var(--second);
}
.words {
  position: absolute;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.words > * {
  margin: 0;
}
.ui-window {
  position: absolute;
  background: var(--ground);
  border: 2px solid var(--hair);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 20px 56px rgba(25, 40, 35, 0.08);
  box-sizing: border-box;
}
.ui-radio {
  width: 18px;
  height: 18px;
  border-radius: 999px;
  border: 2px solid var(--second);
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: var(--ground);
}
.ui-radio-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--accent);
}
